mapper.select:
SELECT COUNT(*)
FROM estate.apt_trade
WHERE deal_year = #{dealYear}
AND deal_month = #{dealMonth}
AND deal_day = #{dealDay}

SELECT COUNT(*)
FROM estate.apt_rent
WHERE deal_year = #{dealYear}
AND deal_month = #{dealMonth}
AND deal_day = #{dealDay}

INSERT INTO map.bus_stop_info ( city_mgmt_name, city_name, city_code, mobile_short_no, stop_name, stop_code, lon, lat, collected_on) SELECT t.city_mgmt_name, t.city_name, t.city_code, t.mobile_short_no, t.stop_name, t.stop_code, -- 입력은 4326 → 저장은 3857(x/y) ST_X(ST_Transform(ST_SetSRID(ST_MakePoint(t.lon, t.lat), 4326), 3857)) AS lon, ST_Y(ST_Transform(ST_SetSRID(ST_MakePoint(t.lon, t.lat), 4326), 3857)) AS lat, t.collected_on FROM ( VALUES
(#{i.cityMgmtName}, #{i.cityName}, #{i.cityCode}, #{i.mobileShortNo}, #{i.stopName}, #{i.stopCode}, #{i.lon}, #{i.lat}, #{i.collectedOn})
) AS t(city_mgmt_name, city_name, city_code, mobile_short_no, stop_name, stop_code, lon, lat, collected_on) WHERE t.lon BETWEEN -180 AND 180 AND t.lat BETWEEN -85.05112878 AND 85.05112878 ON CONFLICT (stop_code) DO NOTHING RETURNING stop_code

INSERT INTO map.pharmacy ( hpid, duty_name, duty_addr, duty_tel1, duty_fax, duty_time1s, duty_time1c, duty_time2s, duty_time2c, duty_time3s, duty_time3c, duty_time4s, duty_time4c, duty_time5s, duty_time5c, duty_time6s, duty_time6c, wgs84_lon, wgs84_lat, geom, post_cdn1, post_cdn2, rnum, collected_on ) SELECT t.hpid, t.duty_name, t.duty_addr, t.duty_tel1, t.duty_fax, t.duty_time1s, t.duty_time1c, t.duty_time2s, t.duty_time2c, t.duty_time3s, t.duty_time3c, t.duty_time4s, t.duty_time4c, t.duty_time5s, t.duty_time5c, t.duty_time6s, t.duty_time6c, ST_X(ST_Transform(ST_SetSRID(ST_MakePoint(t.wgs84_lon, t.wgs84_lat), 4326), 3857)) AS wgs84_lon, ST_Y(ST_Transform(ST_SetSRID(ST_MakePoint(t.wgs84_lon, t.wgs84_lat), 4326), 3857)) AS wgs84_lat, ST_SetSRID(ST_MakePoint( ST_X(ST_Transform(ST_SetSRID(ST_MakePoint(t.wgs84_lon, t.wgs84_lat), 4326), 3857)), ST_Y(ST_Transform(ST_SetSRID(ST_MakePoint(t.wgs84_lon, t.wgs84_lat), 4326), 3857)) ), 3857) AS geom, t.post_cdn1, t.post_cdn2, t.rnum, CASE WHEN t.collected_on IS NULL THEN CURRENT_DATE ELSE t.collected_on::DATE END AS collected_on FROM ( VALUES
(#{i.hpid}, #{i.dutyName}, #{i.dutyAddr}, #{i.dutyTel1}, #{i.dutyFax}, #{i.dutyTime1s}, #{i.dutyTime1c}, #{i.dutyTime2s}, #{i.dutyTime2c}, #{i.dutyTime3s}, #{i.dutyTime3c}, #{i.dutyTime4s}, #{i.dutyTime4c}, #{i.dutyTime5s}, #{i.dutyTime5c}, #{i.dutyTime6s}, #{i.dutyTime6c}, #{i.wgs84Lon}, #{i.wgs84Lat}, #{i.postCdn1}, #{i.postCdn2}, #{i.rnum}, #{i.collectedOn})
) AS t(hpid, duty_name, duty_addr, duty_tel1, duty_fax, duty_time1s, duty_time1c, duty_time2s, duty_time2c, duty_time3s, duty_time3c, duty_time4s, duty_time4c, duty_time5s, duty_time5c, duty_time6s, duty_time6c, wgs84_lon, wgs84_lat, post_cdn1, post_cdn2, rnum, collected_on) WHERE t.wgs84_lon BETWEEN -180 AND 180 AND t.wgs84_lat BETWEEN -85.05112878 AND 85.05112878 AND t.hpid IS NOT NULL ON CONFLICT (hpid) DO NOTHING RETURNING hpid

INSERT INTO map.hospital ( hpid, duty_name, duty_addr, duty_tel1, duty_div, duty_div_nam, duty_emcls, duty_emcls_name, duty_eryn, duty_time1s, duty_time1c, duty_time2s, duty_time2c, duty_time3s, duty_time3c, duty_time4s, duty_time4c, duty_time5s, duty_time5c, duty_time6s, duty_time6c, duty_time7s, duty_time7c, wgs84_lon, wgs84_lat, geom, post_cdn1, post_cdn2, rnum, collected_on ) SELECT t.hpid, t.duty_name, t.duty_addr, t.duty_tel1, t.duty_div, t.duty_div_nam, t.duty_emcls, t.duty_emcls_name, t.duty_eryn, t.duty_time1s, t.duty_time1c, t.duty_time2s, t.duty_time2c, t.duty_time3s, t.duty_time3c, t.duty_time4s, t.duty_time4c, t.duty_time5s, t.duty_time5c, t.duty_time6s, t.duty_time6c, t.duty_time7s, t.duty_time7c, ST_X(ST_Transform(ST_SetSRID(ST_MakePoint(t.wgs84_lon, t.wgs84_lat), 4326), 3857)) AS wgs84_lon, ST_Y(ST_Transform(ST_SetSRID(ST_MakePoint(t.wgs84_lon, t.wgs84_lat), 4326), 3857)) AS wgs84_lat, ST_SetSRID(ST_MakePoint( ST_X(ST_Transform(ST_SetSRID(ST_MakePoint(t.wgs84_lon, t.wgs84_lat), 4326), 3857)), ST_Y(ST_Transform(ST_SetSRID(ST_MakePoint(t.wgs84_lon, t.wgs84_lat), 4326), 3857)) ), 3857) AS geom, t.post_cdn1, t.post_cdn2, t.rnum, CASE WHEN t.collected_on IS NULL THEN CURRENT_DATE ELSE t.collected_on::DATE END AS collected_on FROM ( VALUES
(#{i.hpid}, #{i.dutyName}, #{i.dutyAddr}, #{i.dutyTel1}, #{i.dutyDiv}, #{i.dutyDivNam}, #{i.dutyEmcls}, #{i.dutyEmclsName}, #{i.dutyEryn}, #{i.dutyTime1s}, #{i.dutyTime1c}, #{i.dutyTime2s}, #{i.dutyTime2c}, #{i.dutyTime3s}, #{i.dutyTime3c}, #{i.dutyTime4s}, #{i.dutyTime4c}, #{i.dutyTime5s}, #{i.dutyTime5c}, #{i.dutyTime6s}, #{i.dutyTime6c}, #{i.dutyTime7s}, #{i.dutyTime7c}, #{i.wgs84Lon}, #{i.wgs84Lat}, #{i.postCdn1}, #{i.postCdn2}, #{i.rnum}, #{i.collectedOn})
) AS t(hpid, duty_name, duty_addr, duty_tel1, duty_div, duty_div_nam, duty_emcls, duty_emcls_name, duty_eryn, duty_time1s, duty_time1c, duty_time2s, duty_time2c, duty_time3s, duty_time3c, duty_time4s, duty_time4c, duty_time5s, duty_time5c, duty_time6s, duty_time6c, duty_time7s, duty_time7c, wgs84_lon, wgs84_lat, post_cdn1, post_cdn2, rnum, collected_on) WHERE t.wgs84_lon BETWEEN -180 AND 180 AND t.wgs84_lat BETWEEN -85.05112878 AND 85.05112878 AND t.hpid IS NOT NULL ON CONFLICT (hpid) DO NOTHING RETURNING hpid

mapper.insert:
INSERT INTO estate.apt_complex ( apt_seq, sgg_cd, umd_cd, umd_nm, land_cd, bonbun, bubun, jibun, road_nm, road_nm_sgg_cd, road_nm_cd, road_nmb_cd, road_nm_bonbun, road_nm_bubun, apt_nm, build_year, trade_count ) SELECT s.apt_seq, s.sgg_cd, s.umd_cd, s.umd_nm, s.land_cd, s.bonbun, s.bubun, s.jibun, s.road_nm, s.road_nm_sgg_cd, s.road_nm_cd, s.road_nmb_cd, s.road_nm_bonbun, s.road_nm_bubun, s.apt_nm, s.build_year, s.trade_count FROM ( SELECT DISTINCT ON (t.apt_seq) t.apt_seq, t.sgg_cd, t.umd_cd, t.umd_nm, t.land_cd, t.bonbun, t.bubun, t.jibun, t.road_nm, t.road_nm_sgg_cd, t.road_nm_cd, t.road_nmb_cd, t.road_nm_bonbun, t.road_nm_bubun, t.apt_nm, t.build_year, count(*) OVER (PARTITION BY t.apt_seq) AS trade_count FROM estate.apt_trade t WHERE t.apt_seq IS NOT NULL
AND t.sgg_cd = #{sggCd}
ORDER BY t.apt_seq, t.deal_year DESC, t.deal_month DESC, t.deal_day DESC ) s ON CONFLICT (apt_seq) DO UPDATE SET umd_cd = COALESCE(EXCLUDED.umd_cd, estate.apt_complex.umd_cd), umd_nm = COALESCE(EXCLUDED.umd_nm, estate.apt_complex.umd_nm), land_cd = COALESCE(EXCLUDED.land_cd, estate.apt_complex.land_cd), bonbun = COALESCE(EXCLUDED.bonbun, estate.apt_complex.bonbun), bubun = COALESCE(EXCLUDED.bubun, estate.apt_complex.bubun), jibun = COALESCE(EXCLUDED.jibun, estate.apt_complex.jibun), road_nm = COALESCE(EXCLUDED.road_nm, estate.apt_complex.road_nm), road_nm_sgg_cd = COALESCE(EXCLUDED.road_nm_sgg_cd, estate.apt_complex.road_nm_sgg_cd), road_nm_cd = COALESCE(EXCLUDED.road_nm_cd, estate.apt_complex.road_nm_cd), road_nmb_cd = COALESCE(EXCLUDED.road_nmb_cd, estate.apt_complex.road_nmb_cd), road_nm_bonbun = COALESCE(EXCLUDED.road_nm_bonbun, estate.apt_complex.road_nm_bonbun), road_nm_bubun = COALESCE(EXCLUDED.road_nm_bubun, estate.apt_complex.road_nm_bubun), apt_nm = COALESCE(EXCLUDED.apt_nm, estate.apt_complex.apt_nm), build_year = COALESCE(EXCLUDED.build_year, estate.apt_complex.build_year), trade_count = EXCLUDED.trade_count, update_at = now()

INSERT INTO estate.apt_complex ( apt_seq, sgg_cd, umd_nm, jibun, road_nm, road_nm_sgg_cd, road_nm_cd, road_nmb_cd, road_nm_bonbun, road_nm_bubun, apt_nm, build_year, rent_count ) SELECT s.apt_seq, s.sgg_cd, s.umd_nm, s.jibun, s.road_nm, s.road_nm_sgg_cd, s.road_nm_cd, s.road_nmb_cd, s.road_nm_bonbun, s.road_nm_bubun, s.apt_nm, s.build_year, s.rent_count FROM ( SELECT DISTINCT ON (r.apt_seq) r.apt_seq, r.sgg_cd, r.umd_nm, r.jibun, r.road_nm, r.road_nm_sgg_cd, r.road_nm_cd, r.road_nmb_cd, r.road_nm_bonbun, r.road_nm_bubun, r.apt_nm, r.build_year, count(*) OVER (PARTITION BY r.apt_seq) AS rent_count FROM estate.apt_rent r WHERE r.apt_seq IS NOT NULL
AND r.sgg_cd = #{sggCd}
ORDER BY r.apt_seq, r.deal_year DESC, r.deal_month DESC, r.deal_day DESC ) s ON CONFLICT (apt_seq) DO UPDATE SET rent_count = EXCLUDED.rent_count, update_at = now()

mapper.select:
SELECT apt_seq, sgg_cd, umd_cd, umd_nm, land_cd, bonbun, bubun, jibun,
       road_nm, road_nm_sgg_cd, road_nm_cd, road_nmb_cd, road_nm_bonbun, road_nm_bubun,
       apt_nm, geocode_tried
FROM estate.apt_complex
WHERE geocode_status IN ('PENDING', 'FAILED')
  AND geocode_tried < #{maxTries}

    AND sgg_cd = #{sggCd}

ORDER BY (trade_count + rent_count) DESC
LIMIT #{limit}

INSERT INTO estate.apt_trade ( sgg_cd, umd_cd, land_cd, bonbun, bubun, jibun, umd_nm, road_nm, road_nm_sgg_cd, road_nm_cd, road_nm_seq, road_nmb_cd, road_nm_bonbun, road_nm_bubun, apt_nm, apt_dong, apt_seq, build_year, exclu_use_ar, floor, deal_year, deal_month, deal_day, deal_amount, dealing_gbn, cdeal_type, cdeal_day, estate_agent_sgg_nm, sler_gbn, buyer_gbn, rgst_date, land_leasehold_gbn, created_at ) SELECT t.sgg_cd, t.umd_cd, t.land_cd, t.bonbun, t.bubun, t.jibun, t.umd_nm, t.road_nm, t.road_nm_sgg_cd, t.road_nm_cd, t.road_nm_seq, t.road_nmb_cd, t.road_nm_bonbun, t.road_nm_bubun, t.apt_nm, t.apt_dong, t.apt_seq, t.build_year::integer, t.exclu_use_ar::numeric, t.floor::integer, t.deal_year::integer, t.deal_month::integer, t.deal_day::integer, t.deal_amount::bigint, t.dealing_gbn, t.cdeal_type, t.cdeal_day, t.estate_agent_sgg_nm, t.sler_gbn, t.buyer_gbn, t.rgst_date, t.land_leasehold_gbn, CASE WHEN t.created_at IS NULL THEN NOW() ELSE t.created_at::timestamp END FROM ( VALUES
( #{i.sggCd}, #{i.umdCd}, #{i.landCd}, #{i.bonbun}, #{i.bubun}, #{i.jibun}, #{i.umdNm}, #{i.roadNm}, #{i.roadNmSggCd}, #{i.roadNmCd}, #{i.roadNmSeq}, #{i.roadNmbCd}, #{i.roadNmBonbun}, #{i.roadNmBubun}, #{i.aptNm}, #{i.aptDong}, #{i.aptSeq}, #{i.buildYear}, #{i.excluUseAr}, #{i.floor}, #{i.dealYear}, #{i.dealMonth}, #{i.dealDay}, #{i.dealAmount}, #{i.dealingGbn}, #{i.cdealType}, #{i.cdealDay}, #{i.estateAgentSggNm}, #{i.slerGbn}, #{i.buyerGbn}, #{i.rgstDate}, #{i.landLeaseholdGbn}, #{i.createdAt} )
) AS t( sgg_cd, umd_cd, land_cd, bonbun, bubun, jibun, umd_nm, road_nm, road_nm_sgg_cd, road_nm_cd, road_nm_seq, road_nmb_cd, road_nm_bonbun, road_nm_bubun, apt_nm, apt_dong, apt_seq, build_year, exclu_use_ar, floor, deal_year, deal_month, deal_day, deal_amount, dealing_gbn, cdeal_type, cdeal_day, estate_agent_sgg_nm, sler_gbn, buyer_gbn, rgst_date, land_leasehold_gbn, created_at ) ON CONFLICT DO NOTHING RETURNING id::text
